import React, { useState } from 'react';
import {
    Container, Paper, TextField, Button, Typography, Box,
    Avatar, Link, InputAdornment, IconButton,
    Checkbox, FormControlLabel, Alert, Fade
} from '@mui/material';
import { styled } from '@mui/material/styles';
import {
    LockOutlined, Email, Visibility, VisibilityOff,
    Security, AccountBalance, ArrowForward
} from '@mui/icons-material';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../firebase';

const StyledPaper = styled(Paper)(({ theme }) => ({
    background: 'linear-gradient(135deg, #1A1A1A 0%, #0A0A0A 100%)',
    borderRadius: '32px',
    padding: theme.spacing(4),
    boxShadow: '0 25px 50px rgba(0,0,0,0.5), 0 0 0 1px rgba(212,175,55,0.1)',
    position: 'relative',
    overflow: 'hidden',
    '&::before': {
        content: '""',
        position: 'absolute',
        top: '-50%',
        right: '-20%',
        width: '300px',
        height: '300px',
        background: 'radial-gradient(circle, rgba(212,175,55,0.05) 0%, transparent 70%)',
        borderRadius: '50%',
    },
}));

const GradientButton = styled(Button)(({ theme }) => ({
    background: 'linear-gradient(135deg, #D4AF37 0%, #B8860B 100%)',
    color: '#000000',
    padding: '14px',
    borderRadius: '16px',
    textTransform: 'none',
    fontSize: '1rem',
    fontWeight: 700,
    '&:hover': {
        background: 'linear-gradient(135deg, #E5C158 0%, #C9971A 100%)',
        transform: 'translateY(-2px)',
        boxShadow: '0 8px 25px rgba(212,175,55,0.3)',
    },
    transition: 'all 0.3s ease',
}));

function SignIn({ onSwitchToSignUp }) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [rememberMe, setRememberMe] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        
        try {
            await signInWithEmailAndPassword(auth, email, password);
        } catch (error) {
            switch(error.code) {
                case 'auth/user-not-found':
                    setError('No account found with this email');
                    break;
                case 'auth/wrong-password':
                    setError('Incorrect password');
                    break;
                case 'auth/invalid-email':
                    setError('Invalid email format');
                    break;
                default:
                    setError('Login failed. Please try again');
                    break;
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <Box sx={{ 
            minHeight: '100vh', 
            display: 'flex', 
            alignItems: 'center',
            background: '#0A0A0A',
            py: 4
        }}>
            <Container maxWidth="sm">
                <Fade in={true} timeout={1000}>
                    <StyledPaper elevation={0}>
                        <Box sx={{ textAlign: 'center', mb: 4 }}>
                            <Avatar sx={{ 
                                width: 80, 
                                height: 80, 
                                background: 'linear-gradient(135deg, #D4AF37 0%, #B8860B 100%)',
                                margin: '0 auto 16px',
                                boxShadow: '0 8px 20px rgba(212,175,55,0.3)'
                            }}>
                                <AccountBalance sx={{ fontSize: 40, color: '#000000' }} />
                            </Avatar>
                            <Typography variant="h4" sx={{ fontWeight: 700, color: '#D4AF37' }}>
                                QUINCORE BANK
                            </Typography>
                            <Typography variant="body1" sx={{ color: '#888', mt: 1 }}>
                                Welcome back to elite banking
                            </Typography>
                        </Box>

                        {error && (
                            <Alert severity="error" sx={{ mb: 3, borderRadius: '12px' }}>
                                {error}
                            </Alert>
                        )}

                        <form onSubmit={handleSubmit}>
                            <TextField
                                fullWidth
                                label="Email Address"
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                required
                                sx={{ mb: 2, '& .MuiOutlinedInput-root': { bgcolor: '#1A1A1A', '& fieldset': { borderColor: '#333' } } }}
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <Email sx={{ color: '#D4AF37' }} />
                                        </InputAdornment>
                                    ),
                                }}
                            />

                            <TextField
                                fullWidth
                                label="Password"
                                type={showPassword ? 'text' : 'password'}
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                                sx={{ mb: 2, '& .MuiOutlinedInput-root': { bgcolor: '#1A1A1A', '& fieldset': { borderColor: '#333' } } }}
                                InputProps={{
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <LockOutlined sx={{ color: '#D4AF37' }} />
                                        </InputAdornment>
                                    ),
                                    endAdornment: (
                                        <InputAdornment position="end">
                                            <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                                                {showPassword ? <VisibilityOff sx={{ color: '#888' }} /> : <Visibility sx={{ color: '#888' }} />}
                                            </IconButton>
                                        </InputAdornment>
                                    ),
                                }}
                            />

                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
                                <FormControlLabel
                                    control={<Checkbox checked={rememberMe} onChange={(e) => setRememberMe(e.target.checked)} sx={{ color: '#D4AF37' }} />}
                                    label={<Typography sx={{ color: '#888' }}>Remember me</Typography>}
                                />
                                <Link href="#" sx={{ color: '#D4AF37', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>
                                    Forgot password?
                                </Link>
                            </Box>

                            <GradientButton fullWidth type="submit" disabled={loading} endIcon={<ArrowForward />}>
                                {loading ? 'Signing in...' : 'Access Account'}
                            </GradientButton>

                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 2, p: 1.5, bgcolor: '#1A1A1A', borderRadius: '12px' }}>
                                <Security sx={{ color: '#D4AF37', fontSize: 20 }} />
                                <Typography variant="caption" sx={{ color: '#888' }}>
                                    Secure 256-bit encryption · Your wealth is protected
                                </Typography>
                            </Box>

                            <Box sx={{ textAlign: 'center', mt: 3 }}>
                                <Typography variant="body2" sx={{ color: '#888' }}>
                                    Don't have an account?{' '}
                                    <Link href="#" onClick={(e) => { e.preventDefault(); onSwitchToSignUp(); }} sx={{ color: '#D4AF37', fontWeight: 600 }}>
                                        Create Account
                                    </Link>
                                </Typography>
                            </Box>

                            <Box sx={{ textAlign: 'center', mt: 4, pt: 2, borderTop: '1px solid #333' }}>
                                <Typography variant="caption" sx={{ color: '#666' }}>
                                    🌍 QUINCORE BANK · Global Private Banking
                                </Typography>
                            </Box>
                        </form>
                    </StyledPaper>
                </Fade>
            </Container>
        </Box>
    );
}

export default SignIn;